import React from 'react';
import { useNavigate } from 'react-router-dom';
import { logout } from '../services/api'; // Adjust the path to your actual location
import FranchiseListAdmin from './FranchiseListAdmin';
import { Box, Button, Typography } from '@mui/material';

const AdminDashboard = () => {
  const navigate = useNavigate();

  // Handle logout logic
  const handleLogout = async () => {
    try {
      const message = await logout();
      console.log(message); // Optional: Display the success message

      // Clear the token from localStorage
      localStorage.removeItem('token');

      // Navigate to the login page
      navigate('/login');
    } catch (error) {
      console.error('Logout failed:', error);
      alert('There was an error logging out. Please try again.');
    }
  };

  return (
    <Box sx={{ padding: 3 }}>
      {/* Header Section */}
      <Box sx={{ marginBottom: 3, textAlign: 'center' }}>
        <Typography variant="h3" sx={{ color: '#3f51b5', fontWeight: 'bold', marginBottom: 2 }}>
          Welcome to Admin Dashboard
        </Typography>
      </Box>

      {/* Action Buttons */}
      <Box sx={{ display: 'flex', justifyContent: 'center', gap: 2, marginBottom: 3 }}>
        <Button
          variant="contained"
          color="primary"
          onClick={() => navigate('/create-user')}
          sx={{ padding: '10px 20px' }}
        >
          Create User
        </Button>
        <Button
          variant="contained"
          color="secondary"
          onClick={() => navigate('/exam-data')}
          sx={{ padding: '10px 20px' }}
        >
          Manage Exam Data
        </Button>
        <Button
          variant="outlined"
          color="error"
          onClick={handleLogout}
          sx={{ padding: '10px 20px' }}
        >
          Logout
        </Button>
      </Box>

      {/* Franchise List Table */}
      <FranchiseListAdmin />

    </Box>
  );
};

export default AdminDashboard;
